package net.nicomar.nomoregrids.platform;

import java.io.IOException;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.level.*;
import net.minecraft.world.phys.Vec3;
import net.nicomar.nomoregrids.core.*;
import net.nicomar.nomoregrids.geometry.*;
import net.nicomar.nomoregrids.world.CompositeCellEntity;

/** Material hooks operate on exposed components rather than deleting the technical block. */
public final class WorldMaterials {
    private record ExplosionPlan(Map<UUID,PieceRecord> originals,Set<UUID> affected){}
    private static final Map<Explosion,ExplosionPlan> EXPLOSIONS=new WeakHashMap<>();
    private WorldMaterials(){}
    public static void register(){net.neoforged.neoforge.common.NeoForge.EVENT_BUS.register(WorldMaterials.class);}
    @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.HIGHEST)
    public static void detonate(net.neoforged.neoforge.event.level.ExplosionEvent.Detonate event){if(!(event.getLevel() instanceof ServerLevel level))return;var service=NmgRuntime.existing(level);if(service==null||service.quarantined())return;var explosion=event.getExplosion();if(explosion.getBlockInteraction()==Explosion.BlockInteraction.KEEP)return;var planned=plan(level,service,explosion);EXPLOSIONS.put(explosion,planned);var cells=new HashSet<BlockPos>(event.getAffectedBlocks());for(var id:planned.affected)for(var c:planned.originals.get(id).worldOccupation().cells(8))if(level.isLoaded(WorldService.pos(c))&&cells.add(WorldService.pos(c)))event.getAffectedBlocks().add(WorldService.pos(c));}
    private static ExplosionPlan plan(ServerLevel level,WorldService service,Explosion explosion){var records=new HashMap<UUID,PieceRecord>();var affected=new HashSet<UUID>();double radius=explosion.radius()*2;for(var p:service.snapshot().records().values()){
        var b=p.worldOccupation().bounds();var point=new Vec3(Math.clamp(explosion.center().x,b.min().x()/16.0,b.max().x()/16.0),Math.clamp(explosion.center().y,b.min().y()/16.0,b.max().y()/16.0),Math.clamp(explosion.center().z,b.min().z()/16.0,b.max().z()/16.0));if(explosion.center().distanceToSqr(point)>radius*radius||!service.available(p)||p.worldOccupation().cells(8).stream().anyMatch(c->!level.isLoaded(WorldService.pos(c))))continue;records.put(p.pieceId(),p);int samples=0;for(var primitive:PieceQueries.volumes(p,"occupation")){if(samples++>=64)break;var center=new ConvexVolume.Vec(0,0,0);for(var vertex:primitive.vertices())center=center.add(vertex);center=center.scale(1.0/primitive.vertices().size());var target=new Vec3(center.x()/16,center.y()/16,center.z()/16);if(ray(level,service,explosion,p.pieceId(),target)){affected.add(p.pieceId());break;}}
    }return new ExplosionPlan(Map.copyOf(records),Set.copyOf(affected));}
    private static boolean ray(ServerLevel level,WorldService service,Explosion explosion,UUID target,Vec3 end){var start=explosion.center();var delta=end.subtract(start);double length=delta.length();if(length<1e-8)delta=new Vec3(1e-5,0,0);double reach=delta.length()+0.01;var origin=new ConvexVolume.Vec(start.x*16,start.y*16,start.z*16);var direction=new ConvexVolume.Vec(delta.x,delta.y,delta.z);var spans=new ArrayList<net.nicomar.nomoregrids.simulation.contact.BlastRay.Span>();var seen=new HashSet<UUID>();var cells=RayCells.trace(new ConvexVolume.Vec(start.x,start.y,start.z),new ConvexVolume.Vec(end.x,end.y,end.z),65536);
        for(var cell:cells){var pos=WorldService.pos(cell);if(!level.isLoaded(pos))return false;for(var id:service.snapshot().at(cell))if(seen.add(id)){var p=service.snapshot().records().get(id);double resistance=service.available(p)?NativeStates.resolve(p).getExplosionResistance(level,pos,explosion):3600000;for(var volume:PieceQueries.volumes(p,"occupation"))volume.interval(origin,direction,reach*16).ifPresent(interval->spans.add(new net.nicomar.nomoregrids.simulation.contact.BlastRay.Span(id,interval.near()/16,interval.far()/16,resistance)));}
            if(service.snapshot().at(cell).isEmpty()){var state=level.getBlockState(pos);if(!state.isAir()&&!(state.getBlock() instanceof net.nicomar.nomoregrids.world.CompositeCellBlock)){double resistance=Math.max(state.getExplosionResistance(level,pos,explosion),state.getFluidState().isEmpty()?0:state.getFluidState().getExplosionResistance());var shape=state.getCollisionShape(level,pos);if(!state.getFluidState().isEmpty())shape=net.minecraft.world.phys.shapes.Shapes.box(0,0,0,1,state.getFluidState().getHeight(level,pos),1);else if(shape.isEmpty())shape=state.getShape(level,pos);UUID id=UUID.nameUUIDFromBytes(("native-blast|"+pos.asLong()).getBytes(java.nio.charset.StandardCharsets.UTF_8));for(var b:shape.toAabbs())ConvexVolume.box((b.minX+cell.x())*16,(b.minY+cell.y())*16,(b.minZ+cell.z())*16,(b.maxX+cell.x())*16,(b.maxY+cell.y())*16,(b.maxZ+cell.z())*16).interval(origin,direction,reach*16).ifPresent(interval->spans.add(new net.nicomar.nomoregrids.simulation.contact.BlastRay.Span(id,interval.near()/16,interval.far()/16,resistance)));}}
        }return net.nicomar.nomoregrids.simulation.contact.BlastRay.reaches(target,spans,explosion.radius()*(0.7+level.getRandom().nextFloat()*0.6),reach);
    }
    public static Optional<PieceRecord> ground(net.minecraft.world.entity.Entity entity){var body=entity.getBoundingBox();var box=new net.minecraft.world.phys.AABB(body.minX,body.minY-1e-5,body.minZ,body.maxX,body.minY+1e-5,body.maxZ);var pieces=new HashMap<UUID,PieceRecord>();var faces=new HashMap<UUID,List<BoxMesh.Face>>();for(var pos:net.nicomar.nomoregrids.world.LoadedCells.intersecting(entity.level(),box))if(entity.level().isLoaded(pos)&&entity.level().getBlockEntity(pos) instanceof CompositeCellEntity cell&&cell.valid())for(var p:cell.view().replicas())if(!p.flags().contains(PieceRecord.Flag.SUBSTITUTE)&&pieces.putIfAbsent(p.pieceId(),p)==null)faces.put(p.pieceId(),net.nicomar.nomoregrids.diagnostic.GeometryCache.faces(p.geometry().collision().transform(Rotation.of(p.orientation()),p.pivot16(),p.origin16()),4096));var foot=new net.nicomar.nomoregrids.simulation.contact.ContactResolver.Foot(body.minX*16,body.minZ*16,body.maxX*16,body.maxZ*16,body.minY*16);return net.nicomar.nomoregrids.simulation.contact.ContactResolver.ground(foot,faces).map(c->pieces.get(c.piece()));}
    public static void inside(Level level,BlockPos pos,net.minecraft.world.entity.Entity entity,net.minecraft.world.entity.InsideBlockEffectApplier effects,boolean swept){
        if(!(level.getBlockEntity(pos) instanceof CompositeCellEntity cell)||!cell.valid())return;var body=entity.getBoundingBox();var contact=ConvexVolume.box(body.minX*16-1e-6,body.minY*16-1e-6,body.minZ*16-1e-6,body.maxX*16+1e-6,body.maxY*16+1e-6,body.maxZ*16+1e-6);
        for(var p:cell.view().replicas())if(!p.flags().contains(PieceRecord.Flag.SUBSTITUTE)&&PieceQueries.volumes(p,"occupation").stream().anyMatch(v->{var c=v.contact(contact);return c==ConvexVolume.Contact.OVERLAP||c==ConvexVolume.Contact.INDETERMINATE;})){
            if(p.sourceBlockId().value().equals("minecraft:honey_block")){var velocity=entity.getDeltaMovement();double oldY=velocity.y/0.9800000190734863+0.08;if(entity.onGround()||oldY>=-0.08)continue;boolean side=net.nicomar.nomoregrids.diagnostic.GeometryCache.faces(p.geometry().collision().transform(Rotation.of(p.orientation()),p.pivot16(),p.origin16()),4096).stream().anyMatch(face->{if(face.normal().axis()==1)return false;double min=face.normal().axis()==0?body.minX*16:body.minZ*16,max=face.normal().axis()==0?body.maxX*16:body.maxZ*16;return Math.abs((face.normal().sign()<0?max:min)-face.plane())<1e-4;});if(side){double scale=oldY< -0.13?-0.05/oldY:1;entity.setDeltaMovement(velocity.x*scale,(-0.05-0.08)*0.9800000190734863,velocity.z*scale);entity.resetFallDistance();}}
            else if(p.sourceBlockId().value().equals("minecraft:cobweb"))NativeStates.resolve(p).entityInside(level,pos,entity,effects,swept);
        }
    }
    public static List<PieceRecord> exposed(CompositeCellEntity cell,Direction face){
        var result=new ArrayList<PieceRecord>();if(!cell.valid())return result;var at=cell.getBlockPos();
        for(var p:cell.view().replicas())if(!p.flags().contains(PieceRecord.Flag.SUBSTITUTE)){boolean exposed=false;
            for(var volume:PieceQueries.volumes(p,"occupation")){for(var plane:volume.planes()){
                var normal=plane.normal();var dominant=Arrays.stream(Direction6.values()).max(Comparator.comparingDouble(d->d.x*normal.x()+d.y*normal.y()+d.z*normal.z())).orElseThrow();if(face!=null&&!dominant.name().equals(face.name()))continue;var vertices=volume.vertices().stream().filter(v->Math.abs(plane.normal().dot(v)-plane.distance())<ConvexVolume.EPS).toList();if(vertices.size()<3)continue;var center=new ConvexVolume.Vec(0,0,0);for(var vertex:vertices)center=center.add(vertex);center=center.scale(1.0/vertices.size());var samples=new ArrayList<ConvexVolume.Vec>();samples.add(center);for(var vertex:vertices)samples.add(center.scale(0.5).add(vertex.scale(0.5)));
                for(var sample:samples){var point=new Vec3(sample.x()/16,sample.y()/16,sample.z()/16);if(point.x<at.getX()-1e-7||point.x>at.getX()+1+1e-7||point.y<at.getY()-1e-7||point.y>at.getY()+1+1e-7||point.z<at.getZ()-1e-7||point.z>at.getZ()+1+1e-7)continue;var start=point.add(normal.x()*0.05,normal.y()*0.05,normal.z()*0.05);var end=point.add(-normal.x()*1e-7,-normal.y()*1e-7,-normal.z()*1e-7);var own=PieceQueries.ray(p,start,end);if(own.isEmpty()||own.orElseThrow().point().distanceToSqr(point)>1e-10)continue;boolean blocked=false;
                    for(var position:RayCells.trace(new ConvexVolume.Vec(start.x,start.y,start.z),new ConvexVolume.Vec(end.x,end.y,end.z),16)){var pos=WorldService.pos(position);if(cell.getLevel()==null||!cell.getLevel().isLoaded(pos)){blocked=true;break;}if(cell.getLevel().getBlockEntity(pos) instanceof CompositeCellEntity neighbor){for(var other:neighbor.view().replicas())if(!other.pieceId().equals(p.pieceId())&&PieceQueries.ray(other,start,end).map(hit->hit.distance16()<=own.orElseThrow().distance16()+1e-5).orElse(false)){blocked=true;break;}}else{var state=cell.getLevel().getBlockState(pos);var hit=state.getCollisionShape(cell.getLevel(),pos).clip(start,end,pos);if(hit!=null&&hit.getLocation().distanceToSqr(start)<=own.orElseThrow().point().distanceToSqr(start)+1e-10)blocked=true;}if(blocked)break;}
                    if(!blocked){exposed=true;break;}
                }if(exposed)break;
            }if(exposed)break;}if(exposed)result.add(p);
        }return List.copyOf(result);
    }
    public static int fire(CompositeCellEntity cell,BlockGetter level,BlockPos pos,Direction face,boolean spread){int max=0;for(var p:exposed(cell,face))try{var state=NativeStates.resolve(p);max=Math.max(max,spread?state.getFireSpreadSpeed(level,pos,face):state.getFlammability(level,pos,face));}catch(RuntimeException ignored){}return max;}
    public static boolean burn(ServerLevel level,BlockPos pos,Direction face,LivingEntity igniter){
        var service=NmgRuntime.existing(level);if(service==null||service.quarantined()||!(level.getBlockEntity(pos) instanceof CompositeCellEntity cell))return false;
        var candidates=exposed(cell,face);int max=fire(cell,level,pos,face,false);var ids=new HashSet<UUID>();for(var p:candidates){int odds=NativeStates.resolve(p).getFlammability(level,pos,face);if(odds>0&&level.getRandom().nextInt(Math.max(1,max))<odds)ids.add(p.pieceId());}
        try{service.removeWorld(ids,false);return !ids.isEmpty();}catch(IOException|RuntimeException ex){if(service.quarantined())NmgRuntime.failed(level,ex);return false;}
    }
    public static void explode(ServerLevel level,BlockPos pos,Explosion explosion){
        if(explosion.getBlockInteraction()==Explosion.BlockInteraction.KEEP)return;var service=NmgRuntime.existing(level);if(service==null||service.quarantined()||!(level.getBlockEntity(pos) instanceof CompositeCellEntity cell))return;
        var planned=EXPLOSIONS.computeIfAbsent(explosion,e->plan(level,service,e));var ids=new HashSet<UUID>();for(var p:cell.view().replicas())if(planned.affected.contains(p.pieceId())&&Objects.equals(service.snapshot().records().get(p.pieceId()),planned.originals.get(p.pieceId())))ids.add(p.pieceId());
        try{service.removeWorld(ids,true);}catch(IOException|RuntimeException ex){if(service.quarantined())NmgRuntime.failed(level,ex);}
    }
}
